<template><view class="page"><view class="card"><text class="heading">导入{{config?.title}}</text><text class="muted">{{farmName || '当前经营主体'}} · 最多500行、2MB；使用CSV模板。</text><view class="buttons"><button size="mini" :disabled="busy" @click="templateFile">下载模板</button><button size="mini" :disabled="busy" @click="pick">选择CSV文件</button></view><textarea v-model="content" :disabled="busy||started" :maxlength="2000000" placeholder="也可粘贴CSV内容。APP支持从表格复制后粘贴。"/><view class="buttons"><button :disabled="busy||started" size="mini" @click="preview">校验并预览</button><button v-if="started" :disabled="busy" size="mini" @click="reset">开始新的导入</button></view><text class="muted">先预览后确认；已成功的行不会重复提交。网络结果不明确的行须先核对台账。</text></view><view v-if="error" class="error">{{error}}</view><view v-if="items.length" class="card"><text class="heading">预览 {{items.length}} 行</text><text class="muted">成功 {{items.filter(r=>r.state==='成功').length}} · 待导入 {{items.filter(r=>r.state==='待导入').length}}</text><view v-for="r in items" :key="r.line" class="record"><text>第{{r.line}}行 · {{r.name}}</text><text class="muted">{{r.state}} {{r.error}}</text></view></view><view v-if="items.length" class="bottom"><button class="primary" :loading="busy" :disabled="busy||!canSubmit" @click="submit">{{busy?'正在逐行保存':'确认导入有效行'}}</button></view></view></template>
<script setup lang="ts">
import {ref,computed,watch} from 'vue'
import {onLoad,onShow,onHide,onBackPress} from '@dcloudio/uni-app'
import {call,type Row} from '@/api/native-business'
import {importTypes,prepareImport} from '@/api/business-import'
import {chooseCsv,parseCsv,csv,saveText,allRows,contextGuard} from '@/utils/business-files'
import {ensureWorkspaceSession,isProductionOps} from '@/utils/workspace'
import {resolveCurrentFarm} from '@/utils/auth-helper'
const kind=ref(''),content=ref(''),farmId=ref(''),farmName=ref(''),busy=ref(false),error=ref(''),started=ref(false),items=ref<Row[]>([]);let guard:()=>void=()=>{throw new Error('请重新打开导入页')},active=true
const config=computed(()=>importTypes[kind.value]),canSubmit=computed(()=>items.value.some(r=>r.state==='待导入'))
onLoad(o=>{kind.value=String(o?.kind||'')});onShow(async()=>{active=true;try{if(!await ensureWorkspaceSession())return;if(isProductionOps())throw new Error('请切换到用户端');if(!config.value)throw new Error('导入类型无效');if(kind.value==='plots'){const farm=await resolveCurrentFarm();if(!farm)return;farmId.value=String(farm.farmId);farmName.value=farm.farmName||''}guard=contextGuard()}catch(e:any){error.value=e.message}})
watch(content,()=>{if(!started.value)items.value=[]})
function reset(){items.value=[];started.value=false;content.value='';error.value=''}
async function templateFile(){try{if(config.value)await saveText(config.value.title+'导入模板.csv',csv([],config.value.headers.map(k=>({key:k,label:k}))))}catch(e:any){error.value=e.message}}
async function pick(){try{if(started.value)throw new Error('请先开始新的导入');content.value=await chooseCsv();await preview()}catch(e:any){error.value=e.message||'文件选择已取消'}}
async function names(){return new Set((await allRows({key:kind.value,label:config.value.title,url:config.value.url,id:config.value.id,title:config.value.name},kind.value==='plots'?{farmId:farmId.value}:{},guard)).map(r=>String(r[config.value.name]||'').trim().toLowerCase()))}
async function preview(){if(busy.value||started.value)return;busy.value=true;error.value='';try{guard();const raw=parseCsv(content.value),existing=await names(),seen=new Set<string>();items.value=raw.map((r,i)=>{let payload:Row={},message='';try{payload=prepareImport(kind.value,r,farmId.value);const n=String(payload[config.value.name]).trim().toLowerCase();if(seen.has(n))throw new Error('文件内名称重复');seen.add(n);if(existing.has(n))throw new Error('已有同名记录，请核对台账')}catch(e:any){message=e.message}return {line:i+2,name:payload[config.value.name]||Object.values(r)[0],payload,state:message?'校验失败':'待导入',error:message}});guard()}catch(e:any){error.value=e.message;items.value=[]}finally{busy.value=false}}
async function submit(){if(busy.value||!canSubmit.value)return;const yes=await new Promise<boolean>(resolve=>uni.showModal({title:'确认导入？',content:'将逐条新增有效记录；失败或中止不会回滚已成功的行。',success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!yes)return;busy.value=true;started.value=true;error.value='';try{guard();const existing=await names();for(const r of items.value){if(r.state!=='待导入')continue;if(!active)throw new Error('页面已离开，后续导入已停止');guard();const n=String(r.payload[config.value.name]).trim().toLowerCase();if(existing.has(n)){r.state='校验失败';r.error='已存在同名记录';continue}try{await call(config.value.url,'POST',r.payload);r.state='成功';r.error='';existing.add(n);guard()}catch(e:any){r.state='待核对';r.error=e.message+'；请先核对台账，勿重复提交';throw new Error('已停止后续导入；请核对当前行结果')}}}catch(e:any){error.value=e.message}finally{busy.value=false}}
onHide(()=>{active=false});onBackPress(()=>busy.value)
</script>
<style scoped>.page{padding:24rpx 24rpx 180rpx;min-height:100vh;background:#f4f6f2;box-sizing:border-box}.card{padding:28rpx;background:white;border-radius:18rpx;margin-bottom:24rpx}.heading{display:block;font-size:32rpx;font-weight:600}.muted{display:block;font-size:24rpx;color:#666666;line-height:1.7;margin:18rpx 0}.buttons{display:flex;gap:16rpx;flex-wrap:wrap;margin:20rpx 0}.buttons button{margin:0;min-height:84rpx;font-size:26rpx}textarea{width:100%;height:280rpx;background:#f4f6f2;box-sizing:border-box;padding:22rpx;font-size:26rpx}.record{border-top:1rpx solid #e5ece2;padding:20rpx 0;font-size:27rpx}.error{background:#fff0e8;color:#a43d28;padding:24rpx;font-size:26rpx}.bottom{position:fixed;bottom:0;left:0;right:0;background:white;padding:20rpx 28rpx calc(20rpx + env(safe-area-inset-bottom))}.primary{background:#126d43;color:white;font-size:28rpx}</style>
